// Total is how many distinct problems the verdict is reporting.
func (h statusHealth) Total() int { return h.Issues + h.Warnings + len(h.Failed) }

// Healthy reports whether the verdict is "nothing to do". A degraded or unsafe
// freshness severity counts as unhealthy even with no issues: a stale index is
// the failure most likely to make the brain quietly wrong.
func (h statusHealth) Healthy() bool {
	return h.Total() == 0 && (h.Severity == "" || h.Severity == "ok")
}

// Line renders the verdict.
func (h statusHealth) Line(render *tui.Renderer, brainCmd string) string {
	brainCmd = setupBrainCommand(brainCmd)
	if h.Healthy() {
		return render.Mark(tui.MarkDone) + " " + render.PhasePaint(tui.PhaseDone, "healthy")
	}
	parts := make([]string, 0, 4)
	if len(h.Failed) > 0 {
		parts = append(parts, fmt.Sprintf("%s failed", strings.Join(h.Failed, ", ")))
	}
	if h.Issues > 0 {
		parts = append(parts, fmt.Sprintf("%d %s", h.Issues, plural(h.Issues, "issue")))
	}
	if h.Warnings > 0 {
		parts = append(parts, fmt.Sprintf("%d %s", h.Warnings, plural(h.Warnings, "warning")))
	}
	if h.Severity != "" && h.Severity != "ok" {
		parts = append(parts, "freshness "+h.Severity)
	}
	phase := tui.PhaseSkipped
	mark := tui.MarkSkipped
	if len(h.Failed) > 0 || h.Severity == "unsafe" {
		phase = tui.PhaseFailed
		mark = tui.MarkFailed
	}
	return render.Mark(mark) + " " + render.PhasePaint(phase, strings.Join(parts, ", ")) +
		render.Dim(" "+render.Dash()+" run `"+brainCmd+" doctor`")
}

func plural(n int, word string) string {
			}
		}
	}

	facts := report.Facts
	factsValue := fmt.Sprintf("%s %s %s",
		render.Bar(facts.Distilled, facts.Sessions, summaryBarWidth),
		render.Ratio(facts.Distilled, facts.Sessions),
		render.Dim("sessions distilled"))
	row("facts", factsValue, "")

	row("backfill", setupPhaseValue(render, report.Backfill, tui.PhaseBackfill, "running in the background"), phaseTiming(timings, "backfill"))
	workspaceValue := render.Mark(tui.MarkDone) + " " + render.PhasePaint(tui.PhaseDaemon, report.Workspace.Name)
	if !report.Workspace.Registered {
		workspaceValue = render.Mark(tui.MarkFailed) + " " + render.PhasePaint(tui.PhaseFailed, report.Workspace.Name+" (registration failed)")
	}
	row("workspace", workspaceValue, phaseTiming(timings, "workspace"))
	row("daemon", setupDaemonValue(render, report.Daemon, brainCmd), phaseTiming(timings, "daemon"))
	// Say plainly, at the moment of install, that this is a persistent service
	// and where its unit lives. "installed (io.entire.brain-watch.1a2b3c4d)"
	// does not tell a first-time reader that something now survives reboots.
	if report.Daemon.Installed && report.Daemon.UnitPath != "" {
		fmt.Fprintf(out, "  %-*s %s\n", setupSummaryLabelWidth, "",
			render.Dim("persistent service, starts again at every login: "+report.Daemon.UnitPath))
	}
	// What the ONE machine-wide watcher covers. Render-only: `setup --json` is a
	// published contract and a new field in it is a breaking change, so this is
	// derived here from the plan rather than added to setupReport.
	if report.Daemon.Installed {
		if coverage := describeWatchPlanCoverage(watchPlan); coverage != "" {
			fmt.Fprintf(out, "  %-*s %s\n", setupSummaryLabelWidth, "", render.Dim(coverage))
	}
	budget := setupResolvedBackfillBudget(setupOpts)
	plan := setupBackfillPlanFor(opts, setupOpts, agent, repoDir, stateDir)
	if plan.Binary == "" {
		progress.Skip("fact backfill: could not resolve this executable's path")
		return setupPhase{State: "skipped", Detail: "executable path unavailable"}
	}
	// Say what this is about to cost BEFORE spending it. Everything the phase
	// used to print — how many sessions, which agent, which model — arrived
	// AFTER the detached child was already running, so the first thing the user
	// could do with the number was read it about a spend already underway. The
	// order is the whole point of a cost line: a user who did not want this has
	// to be able to see it and Ctrl-C, and to be told the one flag that turns it
	// off.
	queued := report.Facts.Pending()
	if budget > 0 && queued > budget {
		queued = budget
	}
	progress.Skip(fmt.Sprintf("fact backfill will SPEND TOKENS now: %s over %d session(s), newest first%s (--no-backfill skips it)",
		setupBackfillSpendLabel(agent, setupOpts), queued, setupBackfillOfLabel(queued, report.Facts.Pending())))

	pid, err := steps.spawnBackfill(ctx, plan)
	if err != nil {
		progress.Skip("fact backfill: " + err.Error())
		report.Warnings = append(report.Warnings, "backfill did not start: "+err.Error())
		return setupPhase{State: "failed", Detail: err.Error()}
	}
	state := setupBackfillState{
		SchemaVersion: setupBackfillStateVersion,
		StartedAt:     steps.now().UTC(),
		PID:           pid,
		Agent:         agent,
		Model:         strings.TrimSpace(setupOpts.model),
		Effort:        strings.TrimSpace(setupOpts.effort),
		MaxSessions:   budget,
		LogPath:       plan.LogPath,
		Sessions:      report.Facts.Pending(),
	}
	if err := writeSetupBackfillState(stateDir, state); err != nil {
		detail := "backfill state not recorded: " + err.Error()
		if stopErr := steps.stopBackfill(pid); stopErr != nil {
			detail += "; stopping untracked backfill: " + stopErr.Error()
		}
		progress.Skip("fact backfill: " + detail)
		report.Warnings = append(report.Warnings, detail)
		return setupPhase{State: "failed", Detail: detail}
	}
	task := progress.Begin("fact backfill")
	task.Update(fmt.Sprintf("fact backfill started in the background: %d session(s), newest first, agent %s (pid %d)",
		queued, agent, pid))
	task.Finish(nil)

